select 
from t_r_data_perm_user_role_grant g
left join t_r_data_perm_role r on r.id = g.role_id
where g.user_id = #{userId}
  and g.effective_time <= #{asOf}
  and (g.expiration_time is null or g.expiration_time > #{asOf})

select 
from t_r_data_perm_user_role_grant
where user_id in
#{uid}
  and effective_time <= #{asOf}
  and (expiration_time is null or expiration_time > #{asOf})

select role_id as roleId, count(*) as cnt from t_r_data_perm_user_role_grant where expiration_time is null and role_id in
#{rid}
group by role_id

select 1
from t_r_data_perm_user_role_grant
where user_id = #{userId}
  and role_id = #{roleId}
  and effective_time <= #{asOf}
  and (expiration_time is null or expiration_time > #{asOf})
limit 1

mapper.update:
update t_r_data_perm_user_role_grant
set expiration_time = #{now},
    end_reason = #{endReason}
where role_id = #{roleId}
  and expiration_time is null
